contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _seq, bytes32 _bh, uint256 _overhead, uint256 _scalar) public {
        bool ok = true;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _seq, _bh, _overhead, _scalar) {
            ok = true;
        } catch {
            ok = false;
        }
        assert(!(ok && c.number() == _number && c.basefee() == _basefee) || ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(address(this) != c.DEPOSITOR_ACCOUNT());
        bool reverted; try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}
